def num(s): s=s.strip(); m={'K':1e3,'M':1e6,'B':1e9}; return float(s[:-1])*m[s[-1]] if s[-1] in m else float(s.replace(',',''))
out={}
for c,rows in D.items():
    v=[(k,num(s)) for k,s in rows]
    med=statistics.median(x for _,x in v[3:])  # skip 3 newest (still accruing)
    ranked=sorted(v[3:],key=lambda x:-x[1])
    outl=[(k,x,round(x/med,1)) for k,x in ranked if x/med>=2][:6]
    if len(outl)<4: outl=[(k,x,round(x/med,1)) for k,x in ranked[:4]]
    base=[(k,x,round(x/med,1)) for k,x in v[3:] if 0.8<=x/med<=1.2][:2]
    out[c]={"median":med,"n":len(v),"outliers":outl,"baseline":base}
    print(f"\n{c}: n={len(v)} median={med/1e6:.2f}M")
    for k,x,r in outl: print(f"  OUT {k} {x/1e6:.1f}M {r}x")
    for k,x,r in base: print(f"  BASE {k} {x/1e6:.2f}M {r}x")
json.dump({"raw":D,"picks":out},open("views.json","w"),indent=1)
